def create_specifier_set(specifiers: str, prereleases: bool | None = None) -> str:
    """Create a SpecifierSet object from a string or iterable of specifiers. specifiers: A string representation of a specifier or a comma-separated list of specifiers, e.g. '>=3.0,!=3.1' -> SpecifierSet object serialized as string. prereleases: Whether to accept prerelease versions if applicable."""
