from packaging.ranges import VersionRange


def create_full_version_range(admit_arbitrary: bool = True, prereleases: bool | None = None) -> dict[str, object]:
    """Create a VersionRange that accepts all PEP 440 versions. admit_arbitrary: whether to admit arbitrary strings as versions; prereleases: whether to include pre-release versions."""
    try:
        result = VersionRange.full(admit_arbitrary=admit_arbitrary, prereleases=prereleases)
        return {
            "range": str(result)
        }
    except Exception as e:
        raise ValueError(f"Failed to create full version range: {str(e)}")

