def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Create a VersionRange that only accepts a single specific version. version: A PEP 440 compliant version string, e.g. '1.0' -> VersionRange singleton for 1.0. prereleases: Whether to include pre-release versions; if None, uses the default behavior. Example: create_singleton_version_range('1.0') -> '1.0'."""
    try:
        range_obj = VersionRange.singleton(version, prereleases=prereleases)
        return str(range_obj)
    except Exception as e:
        if "InvalidVersion" in str(type(e)):
            raise ValueError(f"Invalid version string: {version!r}") from e
        raise ValueError(f"Failed to create version range: {str(e)!r}") from e

