def check_version_range_subset(range1: str, range2: str) -> bool:
    """Check if all versions in range1 are also in range2. range1: first version range specifier string, range2: second version range specifier string to check if range1 is a subset of this. >>> check_version_range_subset('>=1.5,<1.8', '>=1.0,<2.0') -> True"""
    try:
        version_range1 = SpecifierSet(range1).to_range()
        version_range2 = SpecifierSet(range2).to_range()
        return version_range1.is_subset(version_range2)
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")

