from packaging.markers import Marker
from typing import Dict, List, Optional, Union


def evaluate_marker(marker: str, environment: Optional[Dict[str, Union[str, List[str]]]] = None, context: Optional[str] = None) -> bool:
    """Evaluate a marker expression against an environment. marker: A marker expression to evaluate, e.g. 'python_version >= "3.6"' -> True. environment: Mapping containing keys and values to override the detected environment. context: The context in which the marker is evaluated, which influences what marker names are considered valid. Accepted values are "metadata" (default), "lock_file", and "requirement". """
    try:
        marker_obj = Marker(marker)
        return marker_obj.evaluate(environment, context)
    except Exception as e:
        raise ValueError(f"Failed to evaluate marker {marker!r}: {str(e)}")

from packaging.dependency_groups import resolve_dependency_groups as _resolve_dependency_groups
from typing import List, Dict, Any, Union


def resolve_dependency_groups(dependency_groups: Dict[str, List[Union[str, Dict[str, str]]]], groups: List[str]) -> List[str]:
    """Resolve dependency groups to a tuple of requirement strings. dependency_groups: the parsed contents of the [dependency-groups] table from pyproject.toml, groups: the name of the group(s) to resolve, e.g. resolve_dependency_groups({"group1": ["requests"]}, ["group1"]) -> ["requests"]."""
    try:
        return list(_resolve_dependency_groups(dependency_groups, *groups))
    except Exception as e:
        raise ValueError(f"Failed to resolve dependency groups: {str(e)}")

from packaging.licenses import canonicalize_license_expression, InvalidLicenseExpression


def canonicalize_license_expression(raw_license_expression: str) -> str:
    """Normalize a license expression string. raw_license_expression: The License-Expression to canonicalize, e.g. 'mit and apache-2.0' -> 'MIT AND Apache-2.0'."""
    try:
        result = canonicalize_license_expression(raw_license_expression)
        return str(result)
    except InvalidLicenseExpression as e:
        raise ValueError(str(e)) from e
